// HasCpaInstance applies the HasEdge predicate on the "cpa_instance" edge.
func HasCpaInstance() predicate.CPACredential {
	return predicate.CPACredential(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CpaInstanceTable, CpaInstanceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCpaInstanceWith applies the HasEdge predicate on the "cpa_instance" edge with a given conditions (other predicates).
func HasCpaInstanceWith(preds ...predicate.CPAInstance) predicate.CPACredential {
	return predicate.CPACredential(func(s *sql.Selector) {
		step := newCpaInstanceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CPACredential) predicate.CPACredential {
	return predicate.CPACredential(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CPACredential) predicate.CPACredential {
	return predicate.CPACredential(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CPACredential) predicate.CPACredential {
	return predicate.CPACredential(sql.NotPredicates(p))
}
